const entrada = $('When Executed by Another Workflow').first().json || {};
const mensagem = typeof entrada.mensagem === 'string'
  ? entrada.mensagem.trim()
  : String(entrada.mensagem?.text || entrada.mensagem?.content || '').trim();

if (!mensagem) throw new Error('Mensagem de texto vazia.');

return [{
  json: {
    mensagem: {
      tipo: 'text',
      descricao: mensagem,
      texto_extraido: '',
      prompt_rota: ''
    },
    tipoProcessamento: 'text',
    total_token_arquivos: 0
  }
}];

const item = $input.first().json || {};
const entrada = $('When Executed by Another Workflow').first().json || {};
const prompt = $('Refinar prompt').first().json.prompt || '';

const parse = (value, fallback) => {
  if (value === null || value === undefined || value === '') return fallback;
  if (typeof value === 'object') return value;
  try { return JSON.parse(value); } catch { return fallback; }
};
const clean = (value) => String(value || '').trim();

const mensagem = clean(entrada.mensagem?.text || entrada.mensagem?.content || entrada.mensagem);
const historico = (Array.isArray(parse(item.conversa, [])) ? parse(item.conversa, []) : [])
  .map((registro) => registro.json || registro)
  .filter((registro) => clean(registro.mensagem))
  .slice(-12)
  .map((registro) => ({
    role: clean(registro.remetente_wa_user_id) === clean(entrada.wa_user_id) ? 'user' : 'assistant',
    content: clean(registro.mensagem)
  }));

const contextoBusca = parse(item.contexto_busca, {});
const chunks = (Array.isArray(parse(item.conhecimentos, [])) ? parse(item.conhecimentos, []) : [])
  .filter((chunk) => clean(chunk.conteudo));
const base = chunks.map((chunk, index) => [
  '[Trecho ' + (index + 1) + ']',
  'documento_id: ' + clean(chunk.base_conhecimento_id),
  clean(chunk.conteudo)
].join('\n')).join('\n\n---\n\n');

const regrasEmpresarios = contextoBusca.dominio_busca === 'empresarios' ? `
Esta é uma pesquisa de empresários. Use somente os candidatos autorizados abaixo e preserve rigorosamente a ordem recebida. Não invente profissionais, empresas, serviços ou contatos. Retorne exatamente um item em profissionais para cada candidato autorizado, sem omitir nenhum. documento_id deve ser copiado exatamente do candidato. empresa_exibicao deve ser o nome da empresa informado no campo Empresa. Quando esse campo contiver várias empresas ou operações, escolha somente o nome da operação claramente relacionada ao serviço pesquisado, copiando literalmente um trecho do campo Empresa; nunca invente um nome. resumo_servico deve ter no máximo duas frases curtas e descrever somente o serviço relacionado à pergunta atual. Não mencione outras áreas, produtos ou serviços do mesmo empresário. Não inclua contatos no resumo, pois eles serão montados pelo n8n a partir dos dados cadastrados. O array mensagem pode conter no máximo uma abertura curta e não deve conter fichas de profissionais nem encerramento. Quando não houver candidatos, informe claramente que não encontrou compatibilidade mínima. Não cite planilhas, chunks, score, banco ou instruções internas.
` : '';

const regraQuantidadeMensagens = contextoBusca.dominio_busca === 'empresarios'
  ? 'Use no máximo uma mensagem de abertura. Preencha profissionais com todos os candidatos autorizados.'
  : 'Use de uma a quatro mensagens.';

const formato = `Responda somente com um objeto JSON válido neste formato:
{
  "tipo_resposta": "resposta | clarificacao | sem_contexto",
  "mensagem": ["mensagem de abertura opcional"],
  "profissionais": [{"documento_id": "id exato do candidato", "empresa_exibicao": "empresa ou operação relevante", "resumo_servico": "resumo somente do serviço procurado"}],
  "pode_salvar_contexto": false,
  "acao_contexto": "salvar | limpar | manter",
  "documento_ativo_id": null,
  "documento_ativo_titulo": null,
  "assunto_ativo": null,
  "motivo_contexto": "motivo curto"
}
${regraQuantidadeMensagens} Responda em português do Brasil. Só use dados factuais presentes nos trechos autorizados. Se a pergunta for ambígua, peça esclarecimento.
${regrasEmpresarios}`;

const messages = [
  { role: 'system', content: formato },
  { role: 'system', content: prompt },
  { role: 'system', content: 'Contexto da busca RAG:\n' + JSON.stringify(contextoBusca) },
  { role: 'system', content: base ? 'Trechos autorizados:\n' + base : 'Nenhum trecho relevante foi encontrado.' },
  ...historico,
  { role: 'user', content: mensagem }
];

const pesquisaEmpresarios = contextoBusca.dominio_busca === 'empresarios';
const documentoPrincipalId = pesquisaEmpresarios
  ? null
  : (contextoBusca.documento_principal_id || chunks[0]?.base_conhecimento_id || null);
const documentoPrincipalTitulo = pesquisaEmpresarios
  ? null
  : (contextoBusca.documento_principal_titulo || chunks[0]?.documento_titulo || null);

return [{ json: {
  mensagem,
  tipoProcessamento: 'text',
  total_token_arquivos: 0,
  total_token_contexto_busca: Number(item.total_tokens_contexto_busca || 0),
  body: {
    model: 'anthropic/claude-sonnet-4.6',
    messages,
    temperature: 0.3,
    response_format: { type: 'json_object' }
  },
  contexto_ia_para_salvar: {
    p_wa_user_id: entrada.wa_user_id,
    p_sessao_token: contextoBusca.sessao_token || null,
    p_documento_ativo_id: documentoPrincipalId,
    p_documento_ativo_titulo: documentoPrincipalTitulo,
    p_assunto_ativo: contextoBusca.assunto_ativo || contextoBusca.pergunta_busca || mensagem,
    p_entidades_ativas_json: contextoBusca.entidades_ativas || {},
    p_ultima_pergunta: mensagem,
    p_score_documento_ativo: contextoBusca.score_documento_principal ?? chunks[0]?.score_documento ?? null,
    p_ttl_minutos: 1440
  }
} }];

// ALTERACAO JSON FINAL DA IA
// A IA final agora retorna um objeto JSON com mensagem[].
// Este node usa a versao ja normalizada/validada em Preparar memoria ativa IA.

const tokensConversaoArquivos = 0;

let tokensContextoBusca = 0;
try {
  tokensContextoBusca = Number($('Refinar json ia').first().json.total_token_contexto_busca || 0);
} catch {}

const tokensGeracaoResposta = Number($('Gerar resposta').first().json.usage?.total_tokens || 0);
const totalTokensExecucao = tokensGeracaoResposta + tokensConversaoArquivos + tokensContextoBusca;

const mensagens = $('Preparar memoria ativa IA').first().json.mensagens_resposta || [];
const respostaArray = Array.isArray(mensagens) && mensagens.length ? mensagens : ['Não consegui concluir a resposta. Tente enviar sua mensagem novamente.'];
const divisor = Math.max(1, respostaArray.length);
const total_tokens = totalTokensExecucao / divisor;

return respostaArray.map(item => ({
  json: {
    resposta: String(item || '').trim(),
    total_tokens,
    tipo_resposta: $('Preparar memoria ativa IA').first().json.tipo_resposta,
    acao_contexto: $('Preparar memoria ativa IA').first().json.acao_contexto,
    debug_tokens: {
      geracao_resposta: tokensGeracaoResposta,
      conversao_arquivos: tokensConversaoArquivos,
      contexto_busca: tokensContextoBusca
    },
    debug_validacao_contexto: $('Preparar memoria ativa IA').first().json.debug_validacao_contexto || {}
  }
}));

const payload = {
  "p_mensagem_id": $input.first().json.id,
  "p_destinatario_wa_user_id": $('When Executed by Another Workflow').first().json.wa_user_id,
  "p_remetente_wa_user_id": "554799051789",
  "p_mensagem": $('Loop Over Items - enviar mensagens').item.json.resposta,
  "p_cliente_id": $('When Executed by Another Workflow').first().json.cliente_id,
  "p_horario_mensagem_api": $now.toUTC().toISO()
}

return {
  payload: JSON.stringify(payload)
}

// ALTERACAO RAG CONTEXTUAL
// A busca agora retorna chunks + metadados da memoria ativa/resolucao de busca.
// Este node agrupa os chunks por documento e preserva dados para o prompt final e para salvar memoria.

function cleanText(value) {
  return String(value || '').trim();
}

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function uniqueCleanList(values) {
  return [...new Set(asArray(values).map(cleanText).filter(Boolean))];
}

function normalizeDocumentList(value) {
  const seen = new Set();

  return asArray(value)
    .map(item => {
      if (!item || typeof item !== 'object') return null;

      const documentoId = cleanText(item.documento_id || item.base_conhecimento_id || item.id);
      if (!documentoId || seen.has(documentoId)) return null;
      seen.add(documentoId);

      return {
        documento_id: documentoId,
        titulo: cleanText(item.titulo || item.documento_titulo || item.nome || '') || null,
        score_documento: item.score_documento ?? item.score ?? null
      };
    })
    .filter(Boolean);
}

function normalizeRejectedIds(value) {
  return uniqueCleanList(asArray(value).map(item => {
    if (item && typeof item === 'object') {
      return item.documento_id || item.base_conhecimento_id || item.id;
    }
    return item;
  }));
}

const itens = $input.all().map(item => item.json || item);
const primeiro = itens[0] || {};

const conversaHistorico =
  primeiro.conversa ||
  primeiro.historico_recente ||
  $('Compilar conversas').first().json.conversa ||
  '[]';

const chunks = itens
  .filter(item => item && cleanText(item.conteudo))
  .sort((a, b) => {
    if (a._dominio === 'empresarios' || b._dominio === 'empresarios') {
      return Number(a.ordem_exibicao || 999999) - Number(b.ordem_exibicao || 999999);
    }
    const docDiff = Number(b.score_documento || 0) - Number(a.score_documento || 0);
    if (docDiff !== 0) return docDiff;
    const chunkDiff = Number(b.score || 0) - Number(a.score || 0);
    if (chunkDiff !== 0) return chunkDiff;
    return Number(a.chunk_index || 0) - Number(b.chunk_index || 0);
  });

const documentosMap = new Map();
for (const chunk of chunks) {
  const documentoId = chunk.base_conhecimento_id || 'sem_documento';
  if (!documentosMap.has(documentoId)) {
    documentosMap.set(documentoId, {
      documento_id: documentoId,
      titulo: chunk.documento_titulo || null,
      score_documento: chunk.score_documento ?? null,
      categoria_id: chunk.categoria_id || null,
      chunks: []
    });
  }

  documentosMap.get(documentoId).chunks.push({
    chunk_id: chunk.chunk_id,
    chunk_index: chunk.chunk_index,
    score: chunk.score,
    origem: chunk.origem,
    conteudo: chunk.conteudo
  });
}

const documentos = [...documentosMap.values()]
  .map(doc => ({
    ...doc,
    chunks: doc.chunks.sort((a, b) => Number(a.chunk_index || 0) - Number(b.chunk_index || 0))
  }))
  .sort((a, b) => Number(b.score_documento || 0) - Number(a.score_documento || 0));

const documentoPrincipal = documentos[0] || null;
const resolucaoBusca = primeiro.resolucao_busca || {};
const contextoIa = primeiro.contexto_ia || {};
const entidadesContextoIa = contextoIa.entidades_ativas && typeof contextoIa.entidades_ativas === 'object'
  ? contextoIa.entidades_ativas
  : {};
const entidadesResolucao = resolucaoBusca.entidades_ativas && typeof resolucaoBusca.entidades_ativas === 'object'
  ? resolucaoBusca.entidades_ativas
  : {};

const consultarBaseConhecimento = primeiro.consultar_base_conhecimento === false || resolucaoBusca.consultar_base_conhecimento === false
  ? false
  : true;
const tipoIntencao = cleanText(
  primeiro.tipo_intencao ||
  resolucaoBusca.tipo_intencao ||
  entidadesResolucao.tipo_intencao ||
  entidadesContextoIa.tipo_intencao ||
  (consultarBaseConhecimento ? 'rag' : 'historico')
);
const metodoBusca = cleanText(
  primeiro.metodo_busca ||
  resolucaoBusca.metodo_busca ||
  entidadesResolucao.metodo_busca ||
  entidadesContextoIa.metodo_busca ||
  (consultarBaseConhecimento ? 'vetorial' : 'nenhum')
);

const documentosApresentadosDaBusca = documentos.map(doc => ({
  documento_id: doc.documento_id,
  titulo: doc.titulo,
  score_documento: doc.score_documento
}));

const dominioBusca = primeiro._dominio || resolucaoBusca.dominio_busca || 'institucional';
const buscaEmpresarios = dominioBusca === 'empresarios';

const documentosApresentados = buscaEmpresarios
  ? documentosApresentadosDaBusca
  : (documentosApresentadosDaBusca.length
  ? documentosApresentadosDaBusca
  : normalizeDocumentList(
      primeiro.documentos_apresentados ||
      resolucaoBusca.documentos_apresentados ||
      entidadesResolucao.documentos_apresentados ||
      entidadesContextoIa.documentos_apresentados ||
      []
    ));

const documentosRejeitados = buscaEmpresarios ? [] : uniqueCleanList([
  ...normalizeRejectedIds(entidadesContextoIa.documentos_rejeitados || []),
  ...normalizeRejectedIds(entidadesResolucao.documentos_rejeitados || []),
  ...normalizeRejectedIds(primeiro.documentos_rejeitados || []),
  ...normalizeRejectedIds(resolucaoBusca.documentos_rejeitados || [])
]);

const identificadoresFortes = buscaEmpresarios ? [] : uniqueCleanList([
  ...uniqueCleanList(entidadesContextoIa.identificadores_fortes || []),
  ...uniqueCleanList(entidadesResolucao.identificadores_fortes || []),
  ...uniqueCleanList(primeiro.identificadores_fortes || []),
  ...uniqueCleanList(resolucaoBusca.identificadores_fortes || [])
]);

const entidadesBase = buscaEmpresarios
  ? { busca_empresarios: entidadesResolucao.busca_empresarios || entidadesContextoIa.busca_empresarios || null }
  : { ...entidadesContextoIa, ...entidadesResolucao };

const entidadesAtivas = {
  ...entidadesBase,
  documentos_apresentados: documentosApresentados,
  documentos_rejeitados: documentosRejeitados,
  identificadores_fortes: identificadoresFortes,
  tipo_intencao: tipoIntencao,
  metodo_busca: metodoBusca
};

const contextoBusca = {
  rag_contextual: primeiro._rag_contextual === false ? false : consultarBaseConhecimento,
  consultar_base_conhecimento: consultarBaseConhecimento,
  tipo_intencao: tipoIntencao,
  metodo_busca: metodoBusca,
  identificadores_fortes: identificadoresFortes,
  documentos_rejeitados: documentosRejeitados,
  documentos_apresentados: documentosApresentados,
  sessao_token: primeiro.sessao_token || null,
  pergunta_busca: primeiro.pergunta_busca || resolucaoBusca.pergunta_busca || '',
  pergunta_original: primeiro.pergunta_original || resolucaoBusca.pergunta_original || '',
  usar_documento_ativo: Boolean(primeiro.usar_documento_ativo || resolucaoBusca.usar_documento_ativo),
  documento_ativo_id: buscaEmpresarios ? null : (primeiro.documento_ativo_id || resolucaoBusca.documento_ativo_id || contextoIa.documento_ativo_id || null),
  documento_ativo_titulo: buscaEmpresarios ? null : (primeiro.documento_ativo_titulo || resolucaoBusca.documento_ativo_titulo || contextoIa.documento_ativo_titulo || null),
  precisa_clarificacao: Boolean(primeiro.precisa_clarificacao || resolucaoBusca.precisa_clarificacao),
  pergunta_clarificacao: primeiro.pergunta_clarificacao || resolucaoBusca.pergunta_clarificacao || null,
  motivo_resolucao: resolucaoBusca.motivo || null,
  assunto_ativo: resolucaoBusca.assunto_ativo || contextoIa.assunto_ativo || null,
  entidades_ativas: entidadesAtivas,
  documento_principal_id: buscaEmpresarios ? null : (documentoPrincipal?.documento_id || null),
  documento_principal_titulo: buscaEmpresarios ? null : (documentoPrincipal?.titulo || null),
  score_documento_principal: documentoPrincipal?.score_documento ?? null,
  total_documentos: documentos.length,
  total_chunks: chunks.length,
  dominio_busca: dominioBusca,
  total_resultados_empresarios: Number(primeiro.total_resultados_empresarios || 0),
  total_restantes_empresarios: Number(primeiro.total_restantes_empresarios || 0),
  total_tokens_contexto_busca: Number(primeiro.total_tokens_contexto_busca || resolucaoBusca.total_tokens_resolucao_busca || 0),
  documentos
};

return [
  {
    json: {
      conversa: conversaHistorico,
      historico_recente: conversaHistorico,
      conhecimentos: JSON.stringify(chunks),
      contexto_busca: JSON.stringify(contextoBusca),
      total_tokens_contexto_busca: contextoBusca.total_tokens_contexto_busca
    }
  }
];

function cleanText(value) {
  return String(value || '').trim();
}

function parseJsonSafe(value, fallback = {}) {
  if (!value) return fallback;
  if (typeof value === 'object') return value;
  try {
    return JSON.parse(value);
  } catch {}

  const match = String(value).match(/\{[\s\S]*\}/);
  if (match) {
    try {
      return JSON.parse(match[0]);
    } catch {}
  }

  return fallback;
}

function parseContextoBusca() {
  try {
    return parseJsonSafe($('Compilar chunks relevantes').first().json.contexto_busca, {});
  } catch {
    return {};
  }
}

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function uniqueCleanList(values) {
  return [...new Set(asArray(values).map(cleanText).filter(Boolean))];
}

function normalizarDocumentoResumo(value) {
  const seen = new Set();
  return asArray(value)
    .map(item => {
      if (!item || typeof item !== 'object') return null;
      const documentoId = cleanText(item.documento_id || item.base_conhecimento_id || item.id);
      if (!documentoId || seen.has(documentoId)) return null;
      seen.add(documentoId);
      return {
        documento_id: documentoId,
        titulo: cleanText(item.titulo || item.documento_titulo || item.nome || '') || null,
        score_documento: item.score_documento ?? item.score ?? null
      };
    })
    .filter(Boolean);
}

function normalizarIds(value) {
  return uniqueCleanList(asArray(value).map(item => {
    if (item && typeof item === 'object') {
      return item.documento_id || item.base_conhecimento_id || item.id;
    }
    return item;
  }));
}

function normalizarMensagens(value) {
  let mensagens = [];

  if (Array.isArray(value)) {
    mensagens = value;
  } else if (typeof value === 'string' && cleanText(value)) {
    mensagens = [value];
  }

  mensagens = mensagens
    .map(msg => cleanText(msg))
    .filter(Boolean);

  if (!mensagens.length) {
    mensagens = ['N\u00e3o consegui montar uma resposta segura com o contexto dispon\u00edvel. Pode me mandar mais detalhes?'];
  }

  if (mensagens.length > 8) {
    mensagens = [
      ...mensagens.slice(0, 7),
      mensagens.slice(7).join('\n\n')
    ].filter(Boolean);
  }

  return mensagens;
}

function normalizarTipoResposta(value) {
  const tipo = cleanText(value).toLowerCase();
  if (['resposta', 'clarificacao', 'sem_contexto'].includes(tipo)) return tipo;
  return 'resposta';
}

function normalizarAcaoContexto(value, tipoResposta) {
  const acao = cleanText(value).toLowerCase();
  if (['salvar', 'limpar', 'manter'].includes(acao)) return acao;
  return tipoResposta === 'resposta' ? 'salvar' : 'limpar';
}

function getDocumentos(contextoBusca) {
  return Array.isArray(contextoBusca.documentos) ? contextoBusca.documentos : [];
}

function docById(documentos, id) {
  if (!id) return null;
  return documentos.find(doc => cleanText(doc.documento_id) === cleanText(id)) || null;
}

function titleHasTerm(title, term) {
  return cleanText(title).toLowerCase().includes(cleanText(term).toLowerCase());
}

function extractStrongTerms(text) {
  const raw = String(text || '');
  const upperTerms = raw.match(/\b[A-Z0-9]{2,}\b/g) || [];
  return [...new Set(upperTerms.map(term => term.trim()).filter(term => term.length >= 2))];
}

function montarEntidadesBusca(contextoBusca) {
  const entidadesOriginais = contextoBusca.entidades_ativas && typeof contextoBusca.entidades_ativas === 'object'
    ? contextoBusca.entidades_ativas
    : {};

  const documentosApresentados = normalizarDocumentoResumo(
    contextoBusca.documentos_apresentados || entidadesOriginais.documentos_apresentados || []
  );
  const documentosRejeitados = normalizarIds(
    contextoBusca.documentos_rejeitados || entidadesOriginais.documentos_rejeitados || []
  );
  const identificadoresFortes = uniqueCleanList(
    contextoBusca.identificadores_fortes || entidadesOriginais.identificadores_fortes || []
  );
  const tipoIntencao = cleanText(contextoBusca.tipo_intencao || entidadesOriginais.tipo_intencao);
  const metodoBusca = cleanText(contextoBusca.metodo_busca || entidadesOriginais.metodo_busca);

  return {
    entidades: {
      ...entidadesOriginais,
      documentos_apresentados: documentosApresentados,
      documentos_rejeitados: documentosRejeitados,
      identificadores_fortes: identificadoresFortes,
      tipo_intencao: tipoIntencao || null,
      metodo_busca: metodoBusca || null
    },
    tem_estado_busca: Boolean(
      documentosApresentados.length ||
      documentosRejeitados.length ||
      identificadoresFortes.length ||
      tipoIntencao ||
      metodoBusca
    )
  };
}

function gerarClarificacaoConflito(contextoBusca, candidateDoc) {
  const activeTitle = cleanText(contextoBusca.documento_ativo_titulo) || 'o contexto anterior';
  const candidateTitle = cleanText(candidateDoc?.titulo || candidateDoc?.documento_titulo) || 'outro documento encontrado';

  return [
    'Eu estava usando o contexto de "' + activeTitle + '", mas sua pergunta parece mudar para outro documento ou assunto.',
    'Encontrei "' + candidateTitle + '" na base. Voc\u00ea quer que eu consulte esse documento?'
  ];
}

function existeConflitoDocumento(contextoBusca, documentos, respostaJson) {
  const pergunta = [
    contextoBusca.pergunta_original,
    contextoBusca.pergunta_busca
  ].map(cleanText).join(' ').toLowerCase();

  const activeId = cleanText(contextoBusca.documento_ativo_id);
  const activeTitle = cleanText(contextoBusca.documento_ativo_titulo);
  const respostaDocId = cleanText(respostaJson.documento_ativo_id);
  const respostaDoc = docById(documentos, respostaDocId);

  if (!activeId || !activeTitle || !documentos.length) {
    return { conflito: false, candidateDoc: null, motivo: null };
  }

  const docsDiferentes = documentos.filter(doc => cleanText(doc.documento_id) && cleanText(doc.documento_id) !== activeId);
  const perguntaFalaContrato = /\bcontrat[oa]s?\b/i.test(pergunta);
  const activeEhContrato = /\bcontrat[oa]s?\b/i.test(activeTitle);
  const contratoCandidato = docsDiferentes.find(doc => /\bcontrat[oa]s?\b/i.test(cleanText(doc.titulo)));

  if (perguntaFalaContrato && !activeEhContrato && contratoCandidato) {
    return { conflito: true, candidateDoc: contratoCandidato, motivo: 'pergunta_sobre_contrato_fora_do_documento_ativo' };
  }

  const termosFortes = extractStrongTerms((contextoBusca.pergunta_original || '') + ' ' + (contextoBusca.pergunta_busca || ''));
  for (const termo of termosFortes) {
    const activeTemTermo = titleHasTerm(activeTitle, termo);
    const candidato = docsDiferentes.find(doc => titleHasTerm(doc.titulo, termo));
    if (!activeTemTermo && candidato) {
      return { conflito: true, candidateDoc: candidato, motivo: 'termo_forte_aponta_para_outro_documento' };
    }
  }

  if (respostaDocId && respostaDocId === activeId && perguntaFalaContrato && !activeEhContrato) {
    return { conflito: true, candidateDoc: contratoCandidato || respostaDoc, motivo: 'ia_tentou_salvar_documento_ativo_incompativel' };
  }

  return { conflito: false, candidateDoc: null, motivo: null };
}

function montarTextoResposta(mensagens) {
  return mensagens.join('\n\n');
}

function extrairCampo(conteudo, rotulo) {
  const linha = cleanText(conteudo).split(/\r?\n/).find(item => item.toLowerCase().startsWith(rotulo.toLowerCase() + ':'));
  return linha ? cleanText(linha.slice(linha.indexOf(':') + 1)) : '';
}

function normalizarComparacao(value) {
  return cleanText(value).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ');
}

function montarMensagensEmpresarios(resposta, docs, contexto) {
  const profissionaisIa = Array.isArray(resposta.profissionais) ? resposta.profissionais : [];
  const porDocumento = new Map(
    profissionaisIa
      .filter(item => item && typeof item === 'object' && cleanText(item.documento_id))
      .map(item => [cleanText(item.documento_id), item])
  );
  const mensagens = ['Encontrei estas empresas para o serviço que você procura:'];
  const consulta = cleanText(contexto.pergunta_busca || contexto.pergunta_original || 'o serviço informado');

  for (const doc of docs) {
    const conteudo = cleanText(doc.chunks?.[0]?.conteudo);
    const empresaOriginal = extrairCampo(conteudo, 'Empresa') || cleanText(doc.titulo) || 'Empresa cadastrada';
    const itemIa = porDocumento.get(cleanText(doc.documento_id)) || {};
    const empresaSugerida = cleanText(itemIa.empresa_exibicao);
    const empresa = empresaSugerida && normalizarComparacao(empresaOriginal).includes(normalizarComparacao(empresaSugerida))
      ? empresaSugerida
      : empresaOriginal;
    const resumoIa = cleanText(itemIa.resumo_servico).replace(/\s+/g, ' ').slice(0, 420);
    const resumo = resumoIa || ('Possui atuação compatível com a sua busca por ' + consulta + '.');
    const contatos = [
      ['Site', extrairCampo(conteudo, 'Site')],
      ['Telefone', extrairCampo(conteudo, 'Telefone')],
      ['E-mail', extrairCampo(conteudo, 'E-mail')],
      ['Instagram', extrairCampo(conteudo, 'Instagram')],
      ['LinkedIn', extrairCampo(conteudo, 'LinkedIn')]
    ].filter(([, valor]) => cleanText(valor));
    const linhas = ['🏢 *' + empresa + '*', resumo];
    if (contatos.length) {
      linhas.push('📞 *Contatos e redes sociais:*');
      for (const [rotulo, valor] of contatos) linhas.push('• ' + rotulo + ': ' + valor);
    } else {
      linhas.push('Contatos públicos não informados.');
    }
    mensagens.push(linhas.join('\n'));
  }

  const restante = Number(contexto.total_restantes_empresarios || 0);
  if (restante > 0) {
    mensagens.push('Tenho mais ' + restante + ' empresas que podem ajudar. Se quiser, posso mostrar as próximas.');
  }
  return mensagens;
}

