function respostaAgrupaProfissionais(listaMensagens) {
  if (documentos.length < 2) return false;
  return listaMensagens.some((mensagem) => {
    const texto = cleanText(mensagem).toLowerCase();
    const encontrados = documentos.filter((doc) => {
      const marcadores = cleanText(doc.titulo)
        .split(/—|-/)
        .map((item) => cleanText(item).toLowerCase())
        .filter((item) => item.length >= 4);
      return marcadores.some((item) => texto.includes(item));
    });
    return encontrados.length > 1;
  });
}

if (dominioEmpresarios && Boolean(contextoBusca.precisa_clarificacao)) {
