}

const entidadesParaSalvar = (podeSalvarDocumento || deveSalvarEstadoBusca)
  ? estadoBusca.entidades
  : {};

const assuntoParaSalvar = podeSalvarDocumento
  ? (respostaJson.assunto_ativo || contextoBusca.assunto_ativo || contextoBusca.pergunta_busca || contextoBase.p_assunto_ativo)
  : (devePreservarDocumentoAtivo ? (contextoBusca.assunto_ativo || contextoBase.p_assunto_ativo || null) : null);

