        identificadores_fortes_salvos: estadoBusca.entidades.identificadores_fortes?.length || 0
      }
    }
  }
];

function parseJsonSafe(value, fallback) {
  if (!value) return fallback;
  if (Array.isArray(value) || typeof value === 'object') return value;

  try {
    return JSON.parse(value);
  } catch {
    return fallback;
  }
}

function estimarTokens(value) {
  const text = typeof value === 'string' ? value : JSON.stringify(value || '');
  return Math.ceil(text.length / 4);
}

function removerConteudoDoChunk(chunk) {
  if (!chunk || typeof chunk !== 'object') return chunk;

  const {
    conteudo,
    content,
    texto,
    text,
    ...rest
  } = chunk;

  return {
    ...rest,
    conteudo_removido_por_clarificacao: Boolean(conteudo || content || texto || text)
  };
}

function resumirDocumentoParaClarificacao(doc) {
  if (!doc || typeof doc !== 'object') return doc;

  return {
    documento_id: doc.documento_id || doc.base_conhecimento_id || null,
    titulo: doc.titulo || doc.documento_titulo || null,
    score_documento: doc.score_documento ?? null,
    categoria_id: doc.categoria_id || null,
    total_chunks_originais: Array.isArray(doc.chunks) ? doc.chunks.length : 0,
    chunks: []
  };
}

const items = $input.all();

return items.map((item) => {
  const json = item.json || {};

  const conhecimentosOriginal = parseJsonSafe(json.conhecimentos, []);
  const contextoBuscaOriginal = parseJsonSafe(json.contexto_busca, {});

  const precisaClarificacao = Boolean(
    contextoBuscaOriginal.precisa_clarificacao ||
    json.precisa_clarificacao ||
    (
      Array.isArray(conhecimentosOriginal) &&
      conhecimentosOriginal.some(chunk => Boolean(chunk?.precisa_clarificacao))
    )
  );

  if (!precisaClarificacao) {
    return {
      json: {
        ...json,
        debug_otimizacao_clarificacao: {
          aplicada: false,
          motivo: 'contexto_nao_marcado_como_clarificacao',
          chars_conhecimentos_original: JSON.stringify(conhecimentosOriginal).length,
          approx_tokens_conhecimentos_original: estimarTokens(conhecimentosOriginal),
          chars_contexto_busca_original: JSON.stringify(contextoBuscaOriginal).length,
          approx_tokens_contexto_busca_original: estimarTokens(contextoBuscaOriginal)
        }
      },
      binary: item.binary
    };
  }

  const documentosOriginais = Array.isArray(contextoBuscaOriginal.documentos)
    ? contextoBuscaOriginal.documentos
    : [];

  const documentosSemChunks = documentosOriginais.map(resumirDocumentoParaClarificacao);

  const conhecimentosSemConteudo = Array.isArray(conhecimentosOriginal)
    ? conhecimentosOriginal.map(removerConteudoDoChunk)
    : [];

  const contextoBuscaOtimizado = {
    ...contextoBuscaOriginal,
    documentos: documentosSemChunks,
    chunks_removidos_por_clarificacao: true,
    total_documentos: documentosSemChunks.length,
    total_chunks_originais: documentosOriginais.reduce((total, doc) => {
      return total + (Array.isArray(doc.chunks) ? doc.chunks.length : 0);
    }, 0)
  };

  return {
    json: {
      ...json,
      conhecimentos: JSON.stringify(conhecimentosSemConteudo),
      contexto_busca: JSON.stringify(contextoBuscaOtimizado),
      debug_otimizacao_clarificacao: {
        aplicada: true,
        motivo: 'precisa_clarificacao_true',
        documentos_preservados: documentosSemChunks.length,
        chunks_contexto_busca_removidos: contextoBuscaOtimizado.total_chunks_originais,
        chunks_conhecimentos_sem_conteudo: conhecimentosSemConteudo.length,
        chars_conhecimentos_original: JSON.stringify(conhecimentosOriginal).length,
        chars_conhecimentos_otimizado: JSON.stringify(conhecimentosSemConteudo).length,
        approx_tokens_conhecimentos_original: estimarTokens(conhecimentosOriginal),
        approx_tokens_conhecimentos_otimizado: estimarTokens(conhecimentosSemConteudo),
        chars_contexto_busca_original: JSON.stringify(contextoBuscaOriginal).length,
        chars_contexto_busca_otimizado: JSON.stringify(contextoBuscaOtimizado).length,
        approx_tokens_contexto_busca_original: estimarTokens(contextoBuscaOriginal),
        approx_tokens_contexto_busca_otimizado: estimarTokens(contextoBuscaOtimizado)
      }
    },
    binary: item.binary
  };
});

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();
